import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.BBXLvvRa.js";const u=JSON.parse(`{"title":"Open Standards","description":"Express processes and decisions in open standards like BPMN, DMN, and FEEL so your models and integration code outlive any single vendor's tool.","frontmatter":{"title":"Open Standards","description":"Express processes and decisions in open standards like BPMN, DMN, and FEEL so your models and integration code outlive any single vendor's tool."},"headers":[],"relativePath":"docs/principles/open-standards.md","filePath":"docs/principles/open-standards.md"}`),r={name:"docs/principles/open-standards.md"};function s(i,e,d,l,c,p){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="open-standards" tabindex="-1">Open Standards <a class="header-anchor" href="#open-standards" aria-label="Permalink to &quot;Open Standards&quot;">​</a></h1><blockquote><p>Open Standards <strong>over</strong> Proprietary Solutions</p></blockquote><p><em>Build your process automation on open, published specifications so your models outlive the tool that runs them today.</em></p><p>This principle asserts that you should express processes and decisions in open, vendor-neutral specifications rather than a vendor&#39;s proprietary format. The standards that matter most are <a href="https://www.omg.org/spec/BPMN/" target="_blank" rel="noreferrer">BPMN</a> (Business Process Model and Notation), <a href="https://www.omg.org/spec/DMN/" target="_blank" rel="noreferrer">DMN</a> (Decision Model and Notation), and <a href="https://www.omg.org/spec/DMN/" target="_blank" rel="noreferrer">FEEL</a> (Friendly Enough Expression Language, the expression language defined inside DMN). We hold this because automation assets are long-lived: they encode years of business knowledge, and that knowledge should not be locked to one tool&#39;s licensing, roadmap, or lifecycle.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>Proprietary models trap knowledge. When a process lives in a closed format, it means something only inside one vendor&#39;s runtime. Migration to another engine, whether triggered by a pricing change, an end of support, or a better fit, then becomes a manual rewrite of every diagram, listener, and expression. Switching cost, not technical fit, ends up deciding your architecture for you. That is vendor lock-in.</p><p>Skills do not transfer either. A developer who knows BPMN can read a diagram from any compliant engine, whether Camunda, Operaton, or Flowable. A developer who only knows one vendor&#39;s canvas has to relearn each move. Open standards keep hiring, onboarding, and consulting portable across the whole ecosystem.</p><p>The subtle trap is the gap between supporting a standard and extending it. Most engines read and write valid BPMN, then add proprietary attributes, task types, or scripting for the parts that matter most in production. Lean on those extensions and your diagram still opens elsewhere but no longer runs there. Portability erodes one convenient shortcut at a time.</p><h2 id="keep-your-integration-engine-agnostic" tabindex="-1">Keep your integration engine-agnostic <a class="header-anchor" href="#keep-your-integration-engine-agnostic" aria-label="Permalink to &quot;Keep your integration engine-agnostic&quot;">​</a></h2><p>Open standards cover the model. Your application code needs the same treatment, because a process application also binds to the engine through its client library, task workers, and APIs. Couple your code tightly to one vendor&#39;s client and you have simply moved the lock-in from the model into the codebase.</p><p>This is the gap the <a href="https://github.com/bpm-crafters/process-engine-api" target="_blank" rel="noreferrer">Process Engine API</a> closes. We build and maintain it as an engine-agnostic layer: one API with adapters for the common engines, including Camunda 7, Camunda 8, and CIB seven, so your integration code separates <em>how you talk to an engine</em> from <em>which engine you chose</em>. Migrating between engines then costs little or no change to your application, the same portability that open standards give your models, now applied to the integration itself.</p><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2><ul><li><strong>Model in BPMN and DMN first.</strong> Reach for the open element before a vendor-specific one, and treat proprietary constructs as the exception you justify.</li><li><strong>Isolate vendor extensions.</strong> Keep engine-specific attributes, connectors, and glue code in a thin, clearly marked layer so the core model stays portable.</li><li><strong>Validate against the spec, not just the tool.</strong> Round-trip your models through the standard&#39;s XML schema or a second modeler to catch constructs that only one engine understands. The vendor-neutral <a href="https://github.com/bpmn-miwg" target="_blank" rel="noreferrer">OMG BPMN Model Interchange Working Group (MIWG)</a> publishes a shared test suite for exactly this, so you can see how faithfully each tool reads and writes the standard.</li><li><strong>Push logic out of proprietary scripts.</strong> Implement business logic in versioned service code or DMN tables rather than inline vendor scripting that no other engine can execute.</li><li><strong>Decouple workers from the engine.</strong> Talk to the engine over a documented protocol instead of compiling against it. Job-worker and external-task patterns, or an engine-agnostic layer like the <a href="https://github.com/bpm-crafters/process-engine-api" target="_blank" rel="noreferrer">Process Engine API</a>, keep your task implementations independent of any single runtime.</li><li><strong>Make portability a review criterion.</strong> Ask during design reviews whether the model still runs on another compliant engine, and record every &quot;no&quot; as a deliberate trade-off.</li></ul><h2 id="what-this-doesn-t-mean" tabindex="-1">What this doesn&#39;t mean <a class="header-anchor" href="#what-this-doesn-t-mean" aria-label="Permalink to &quot;What this doesn&#39;t mean&quot;">​</a></h2><p>Open standards are not a ban on vendor features. Proprietary extensions exist because engines compete on real value, including better tooling, performance, connectors, and support, and using them is often the pragmatic choice. The point is one of emphasis and sequencing: reach for the open standard first, adopt proprietary constructs deliberately, and know exactly what portability you trade for the convenience. A closed solution you choose with open eyes is fine. One you back into by default is the risk.</p><h2 id="related-principles" tabindex="-1">Related principles <a class="header-anchor" href="#related-principles" aria-label="Permalink to &quot;Related principles&quot;">​</a></h2><ul><li><a href="/docs/principles/best-practices">Process Automation Best Practices</a>: open beats proprietary for the same reason proven practices beat tool-centric habits, and both keep portable logic out of vendor extensions.</li><li><a href="/docs/principles/business-it-alignment">Fostering Business-IT Alignment</a>: open BPMN and DMN are what make your models readable and changeable by the business.</li></ul>',17)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
